"""Sim feedback wrapper: run pyfcstm ``SimulationRuntime`` against multi-step test scenarios.

Each TestScenario contains a sequence of ScenarioStep entries; each step is
(before_cycles, events, expected_state, expected_vars). The sim wrapper:

1. Parses + builds the model from the supplied DSL.
2. For each scenario:
   a. Constructs ``SimulationRuntime`` with ``abstract_error_mode='log'`` and
      passes ``initial_state`` / ``initial_vars`` for hot-start. **Does NOT
      auto-run an initial cycle** — full control of cycle execution belongs
      to the steps.
   b. For each step in scenario.steps:
        - run ``cycle()`` × ``before_cycles`` (empty cycles)
        - depending on ``events``:
            * ``None``: skip the cycle entirely
            * ``[]``:   ``cycle()`` once (no events injected)
            * list:    ``cycle(events=list)`` once (all events triggered together)
        - capture ``runtime.current_state`` + ``runtime.vars`` post-step
        - assert against ``expected_state`` / ``expected_vars`` if non-None
        - record StepResult with status ('pass' / 'fail' / 'error')
   c. Continue to next step on 'fail' (record violation; keep going); stop on
      'error' (runtime exception, scenario can't continue)
3. Aggregate into SimFeedback (per-scenario ScenarioResult list).
"""

from __future__ import annotations

from typing import Any, Optional

from method.schema import (
    ScenarioResult,
    ScenarioStep,
    SimFeedback,
    StepResult,
    TestScenario,
)


def _state_path_str(state: Any) -> str:
    if state is None:
        return ""
    p = getattr(state, "path", None)
    if isinstance(p, (tuple, list)) and len(p) > 0:
        return ".".join(str(x) for x in p)
    name = getattr(state, "name", None)
    return str(name) if name is not None else str(state)


def _safe_current_state_path(runtime: Any) -> str:
    """Best-effort runtime state capture that never masks the original error.

    ``pyfcstm`` raises from ``runtime.current_state`` after the runtime reaches
    a final/ended configuration.  SD-6 must preserve that situation as
    structured scenario evidence instead of raising a second exception while it
    is already converting the original runtime error into ``StepResult``.
    """

    try:
        return _state_path_str(runtime.current_state)
    except Exception:
        return "<ended>"


def _vars_to_dict(runtime_vars: Any) -> dict[str, Any]:
    try:
        return dict(runtime_vars)
    except Exception:
        return {k: runtime_vars[k] for k in getattr(runtime_vars, "keys", lambda: [])()}


def _safe_vars_dict(runtime: Any) -> dict[str, Any]:
    try:
        return _vars_to_dict(runtime.vars)
    except Exception:
        return {}


def _default_initial_vars(model: Any) -> dict[str, Any]:
    """Return pyfcstm variable defaults in a plain dict when available."""

    defaults: dict[str, Any] = {}
    for name, define in (getattr(model, "defines", {}) or {}).items():
        init = getattr(define, "init", None)
        defaults[str(name)] = getattr(init, "value", init)
    return defaults


def _numeric_equal(a: Any, b: Any) -> bool:
    """Treat int/float numeric equality as equal (1 == 1.0)."""
    if a == b:
        return True
    try:
        return float(a) == float(b)
    except (TypeError, ValueError):
        return False


def _execute_step(runtime: Any, step: ScenarioStep, step_index: int) -> StepResult:
    """Execute one ScenarioStep and produce a StepResult.

    May raise SimulationRuntimeDfsError or other runtime exceptions — caller
    catches them and converts to error status.
    """
    from pyfcstm.simulate import SimulationRuntime  # noqa: F401 (kept for clarity)

    sr = StepResult(
        step_index=step_index,
        step_name=step.name or f"step_{step_index}",
    )

    # 1. before_cycles empty cycles
    for _ in range(step.before_cycles):
        runtime.cycle()

    # 2. events handling
    if step.events is None:
        pass  # skip cycle entirely
    elif step.events == []:
        runtime.cycle()
    else:
        # All events triggered together in a single cycle (supports pseudo-state chained jumps)
        runtime.cycle(events=list(step.events))

    # 3. capture actual state + vars
    sr.actual_state = _safe_current_state_path(runtime)
    sr.actual_vars = _safe_vars_dict(runtime)

    # 4. state assertion (if non-None)
    if step.expected_state is not None:
        sr.state_assertion_ok = (sr.actual_state == step.expected_state)

    # 5. var assertions (None or empty dict => don't care; otherwise check only listed keys)
    expected_vars = step.expected_vars
    if expected_vars is not None and len(expected_vars) > 0:
        mismatches: dict[str, dict[str, Any]] = {}
        for k, v_expected in expected_vars.items():
            v_actual = sr.actual_vars.get(k)
            if not _numeric_equal(v_actual, v_expected):
                mismatches[k] = {"expected": v_expected, "actual": v_actual}
        sr.var_mismatches = mismatches
        sr.var_assertion_ok = (len(mismatches) == 0)

    # 6. step status
    if sr.state_assertion_ok is False or sr.var_assertion_ok is False:
        sr.status = "fail"
    else:
        sr.status = "pass"

    return sr


def _run_one_scenario(model: Any, scenario: TestScenario) -> ScenarioResult:
    """Execute one full TestScenario; produce a ScenarioResult.

    Continues on 'fail' (collects all step violations); stops immediately on
    'error' (runtime exception).
    """
    from pyfcstm.simulate import SimulationRuntime, SimulationRuntimeDfsError

    sresult = ScenarioResult(name=scenario.name, description=scenario.description)

    try:
        # Hot-start: pass initial_state + initial_vars to constructor (pyfcstm native).
        # Note: pyfcstm requires initial_vars (even if empty dict) whenever initial_state
        # is specified. Default-init (no initial_state) leaves the runtime at the root
        # state — the first cycle() then dispatches into the initial leaf via [*] -> X.
        default_vars = _default_initial_vars(model)
        kwargs: dict[str, Any] = {"abstract_error_mode": "log"}
        if scenario.initial_state is not None:
            kwargs["initial_state"] = scenario.initial_state
            kwargs["initial_vars"] = {**default_vars, **(dict(scenario.initial_vars) if scenario.initial_vars else {})}
        elif scenario.initial_vars:
            kwargs["initial_vars"] = {**default_vars, **dict(scenario.initial_vars)}
        runtime = SimulationRuntime(model, **kwargs)
    except SimulationRuntimeDfsError as e:
        sresult.status = "error"
        sresult.setup_error = f"SimulationRuntimeDfsError on construct: {str(e)[:300]}"
        return sresult
    except Exception as e:
        sresult.status = "error"
        sresult.setup_error = f"{type(e).__name__} on construct: {str(e)[:300]}"
        return sresult

    # Empty steps list is valid — just a hot-start sanity check (no cycle, no assertion)
    if not scenario.steps:
        sresult.status = "pass"
        return sresult

    # Execute each step
    hit_runtime_error = False
    for i, step in enumerate(scenario.steps):
        try:
            sr = _execute_step(runtime, step, i)
        except SimulationRuntimeDfsError as e:
            sr = StepResult(
                step_index=i,
                step_name=step.name or f"step_{i}",
                status="error",
                runtime_error=f"SimulationRuntimeDfsError: {str(e)[:300]}",
                actual_state=_safe_current_state_path(runtime),
                actual_vars=_safe_vars_dict(runtime),
            )
            sresult.step_results.append(sr)
            hit_runtime_error = True
            break
        except Exception as e:
            sr = StepResult(
                step_index=i,
                step_name=step.name or f"step_{i}",
                status="error",
                runtime_error=f"{type(e).__name__}: {str(e)[:300]}",
                actual_state=_safe_current_state_path(runtime),
                actual_vars=_safe_vars_dict(runtime),
            )
            sresult.step_results.append(sr)
            hit_runtime_error = True
            break
        sresult.step_results.append(sr)

    # Aggregate scenario status
    if hit_runtime_error:
        sresult.status = "error"
    elif any(s.status == "fail" for s in sresult.step_results):
        sresult.status = "fail"
    else:
        sresult.status = "pass"

    return sresult


def check_sim(
    dsl_text: str,
    scenarios: Optional[list[TestScenario]] = None,
) -> SimFeedback:
    """Run pyfcstm sim against a list of multi-step test scenarios.

    Returns a SimFeedback with per-scenario, per-step detailed results
    (status, actual state/vars, var mismatches, runtime error). The downstream
    Repair agent consumes this directly as feedback.

    If ``scenarios`` is empty/None, returns a setup-only result (no scenarios
    fired); ``ok=True`` if parse+sem succeeds. This matches the agent loop
    contract where scenario generation may produce 0 scenarios in edge cases.
    """
    try:
        from pyfcstm.dsl import parse_with_grammar_entry
        from pyfcstm.model import parse_dsl_node_to_state_machine
    except ImportError as e:
        return SimFeedback(
            ok=False,
            setup_error=f"pyfcstm not installed: {e}",
        )

    # Parse + sem setup
    try:
        ast = parse_with_grammar_entry(dsl_text, "state_machine_dsl")
        model = parse_dsl_node_to_state_machine(ast)
    except Exception as e:
        return SimFeedback(
            ok=False,

    return advisories


def _grounding_role_texts(grounding_map: GroundingMap | None) -> list[str]:
    if grounding_map is None:
        return []
    texts: list[str] = []
    for element in grounding_map.elements:
        if element.element_kind == "variable":
            texts.append(f"{element.element_ref} {element.evidence_text}")
    for value in (grounding_map.source_summary or {}).values():
        if isinstance(value, str):
            texts.append(value)
        elif isinstance(value, (list, tuple)):
            texts.extend(str(item) for item in value)
        elif value is not None:
            texts.append(str(value))
    return texts


def _external_input_role_ledger(
    *,
    nl: str,
    declared_vars: set[str],
    read_only_guard_vars: set[str],
    grounding_map: GroundingMap | None,
) -> dict[str, list[str]]:
    """Build a conservative, sample-agnostic external-input role ledger.

    The ledger is intentionally not a quality gate.  It only downgrades
    high-risk pyfcstm warnings when the NL / SL-1 grounding contains generic
    controller-boundary evidence that a variable is a read-only plant,
    sensor, environment, or capacity input.  It must not depend on benchmark
    case IDs or domain-specific benchmark aliases.
    """

    ledger: dict[str, list[str]] = {}

    def add(name: str, reason: str) -> None:
        if name in declared_vars:
            ledger.setdefault(name, [])
            if reason not in ledger[name]:
                ledger[name].append(reason)

    for name in _external_input_variables_from_nl(nl) & declared_vars:
        add(name, "explicit NL read/external/sensor/input declaration")

    if _PLANT_BOUNDARY_RE.search(nl):
        for name in read_only_guard_vars & declared_vars:
            if _identifier_token_present(nl, name):
                add(name, "NL states continuous/plant/process dynamics are outside the discrete controller")

    if _CAPACITY_BOUNDARY_RE.search(nl):
        for name in read_only_guard_vars & declared_vars:
            if _identifier_token_present(nl, name) and _CAPACITY_LIKE_IDENTIFIER_RE.search(name):
                add(name, "NL describes capacity/limit/margin quantities as controller inputs or bounds")

    for text in _grounding_role_texts(grounding_map):
        if not _EXTERNAL_ROLE_CUE_RE.search(text):
            continue
        for name in read_only_guard_vars & declared_vars:
            if _identifier_token_present(text, name):
                add(name, "SL-1 grounding/assumption text contains generic external-input role cues")

    return ledger


def _guard_vars(item: DesignDiagnosticItem) -> set[str]:
    raw = item.refs.get("guard_vars")
    if isinstance(raw, list):
        return {str(v) for v in raw}
    return set()


def _external_input_advisory_rationale(item: DesignDiagnosticItem, external_input_ledger: dict[str, list[str]]) -> str | None:
    nl_external_vars = set(external_input_ledger)

    def reason_for(names: Iterable[str]) -> str:
        reasons: list[str] = []
        for name in sorted(set(names)):
            for reason in external_input_ledger.get(name, []):
                if reason not in reasons:
                    reasons.append(reason)
        if not reasons:
            return ""
        return " Evidence: " + "; ".join(reasons) + "."

    if item.code == "W_UNWRITTEN_READ_VAR":
        var = str(item.refs.get("var_name") or "")
        if var and var in nl_external_vars:
            return (
                f"Downgraded because `{var}` is NL-grounded as an external "
                "sensor/environment input; adding invented writes would be "
                "less faithful than leaving it read-only."
                + reason_for([var])
            )
    if item.code == "W_GUARD_VARS_NEVER_CHANGE":
        vars_in_guard = _guard_vars(item)
        if vars_in_guard and vars_in_guard.issubset(nl_external_vars):
            return (
                "Downgraded because all guard variables are NL-grounded "
                f"external inputs: {', '.join(sorted(vars_in_guard))}."
                + reason_for(vars_in_guard)
            )
    return None


def _hash_text(text: str) -> str:
    return "sha256:" + hashlib.sha256(text.encode("utf-8")).hexdigest()


def _stage_meta(stage_id: StageId | str, *, ok: bool, status: StageStatus | str | None = None, stage_error: str | None = None) -> StageResultMeta:
    sid = stage_id.value if isinstance(stage_id, StageId) else stage_id
    spec = STAGE_SPECS_BY_ID[sid]
    resolved = status or (StageStatus.OK if ok else StageStatus.FAIL)
    return StageResultMeta(
        stage_id=sid,
        stage_kind=spec.kind,
        enabled=True,
        ran=True,
        status=resolved,
        ok=ok,
        stage_error=stage_error,
    )


def _attach_meta(context: StageContext | None, feedback: Any, meta: StageResultMeta) -> StageResultMeta:
    if hasattr(feedback, "meta"):
        feedback.meta = meta
    if context is not None:
        context.stage_results.append(meta)
    return meta


def _span_to_dict(span: Any) -> dict[str, Any] | None:
    if span is None:
        return None
    return {
        "line": getattr(span, "line", None),
        "column": getattr(span, "column", None),
        "end_line": getattr(span, "end_line", None),
        "end_column": getattr(span, "end_column", None),
    }


def _normalize_ref(value: Any) -> Any:
    if value is None or isinstance(value, (str, int, float, bool)):
        return value
    if hasattr(value, "line") and hasattr(value, "column"):
        return _span_to_dict(value)
    if isinstance(value, dict):
        return {str(k): _normalize_ref(v) for k, v in value.items()}
    if isinstance(value, (list, tuple, set)):
        return [_normalize_ref(v) for v in value]
    return str(value)


def _diag_to_dict(diag: Any) -> dict[str, Any]:
    if isinstance(diag, dict):
        return copy.deepcopy(diag)
    return {
        "code": getattr(diag, "code", None),
        "severity": getattr(diag, "severity", None),
        "message": getattr(diag, "message", ""),
        "span": _span_to_dict(getattr(diag, "span", None)),
        "refs": _normalize_ref(dict(getattr(diag, "refs", {}) or {})),
    }


def _diagnostic_instance_key(diag: dict[str, Any]) -> str:
    code = str(diag.get("code") or "UNKNOWN")
    refs = diag.get("refs") or {}
    preferred_keys = (
        "state_path",
        "from_path",
        "to_path",
        "var_name",
        "event_ref",
        "transition_id",
        "transition_span",
        "reason",
    )
    parts = [f"{key}={refs[key]}" for key in preferred_keys if key in refs and refs[key] is not None]
    if parts:
        return f"{code}:" + ":".join(parts)
    return f"{code}:" + hashlib.sha256(repr(sorted(refs.items())).encode("utf-8")).hexdigest()[:12]


def _extract_suggested_fix_hints(diag: dict[str, Any]) -> list[dict[str, Any]]:
    hints: list[dict[str, Any]] = []
    refs = diag.get("refs") or {}
    for payload in (diag.get("suggested_fix"), refs.get("suggested_fix")):
        if isinstance(payload, dict):
            hints.append(copy.deepcopy(payload))
    code = diag.get("code")
    try:
        from pyfcstm.diagnostics.codes import CODE_REGISTRY

        spec = CODE_REGISTRY.get(code)
        if spec is not None:
            if spec.suggested_fix is not None:
                hints.append(asdict(spec.suggested_fix))
            if spec.for_llm is not None:
                hints.append(
                    {
                        "kind": "for_llm_guidance",
                        "summary": spec.for_llm.summary,
                        "recommended_actions": [dict(item) for item in spec.for_llm.recommended_actions],
                        "do_not": list(spec.for_llm.do_not),
                    }
                )
    except Exception:
        pass
    return hints


def _budget_state_for(diag: dict[str, Any], warning_budget_state: dict[str, BudgetState]) -> BudgetState:
    key = _diagnostic_instance_key(diag)
    if key not in warning_budget_state:
        warning_budget_state[key] = BudgetState(
            instance_key=key,
            diagnostic_code=str(diag.get("code") or "UNKNOWN"),
            repair_count=0,
            budget_remaining=DEFAULT_WARNING_REPAIR_BUDGET,
            budget_exhausted=False,
            last_status="new",
            last_stage=StageId.SD_4_DESIGN.value,
        )
    return warning_budget_state[key]



def mark_warning_repair_attempt(
    warning_budget_state: dict[str, BudgetState],
    instance_keys: Iterable[str],
    *,
    last_status: str = "repair_attempted",
    last_stage: str = StageId.SL_9_REPAIR.value,
) -> dict[str, BudgetState]:
    """Decrement per-instance warning repair budgets after an SL-9 attempt.

    PR-1A only provides the deterministic state transition; later loop wiring
    decides exactly when to call it. Missing keys are ignored so stale review
    evidence cannot create phantom budget entries.
    """
    for key in instance_keys:
        state = warning_budget_state.get(key)
        if state is None or state.budget_exhausted:
            continue
        state.repair_count += 1
        state.budget_remaining = max(0, state.budget_remaining - 1)
        state.budget_exhausted = state.budget_remaining == 0
        state.last_status = last_status
        state.last_stage = last_stage
    return warning_budget_state


def _design_policy_action(
    diag: dict[str, Any],
    state: BudgetState,
    *,
    policy_profile: DesignPolicyProfile = "generated_candidate",
) -> str:
    severity = diag.get("severity")
    code = str(diag.get("code") or "")
    if severity == "error" or code.startswith("E_"):
        return "hard_block"
    if severity == "info" or code.startswith("I_"):
        return "info"
    if not code.startswith("W_"):
        return "requires_policy_classification"
    if policy_profile in {"path_smoke", "audit_only"}:
        return "advisory"
    if code in _ADVISORY_WARNING_CODES:
        return "advisory"
    if code not in _HIGH_RISK_WARNING_CODES:
        return "requires_policy_classification"
    if state.budget_exhausted or state.budget_remaining <= 0:
        return "advisory"
    return "budgeted_repair"


def _design_item_from_diag(
    diag: dict[str, Any],
    state: BudgetState | None = None,
    *,
    policy_profile: DesignPolicyProfile = "generated_candidate",
) -> DesignDiagnosticItem:
    if state is None:
        state = BudgetState(
            instance_key=_diagnostic_instance_key(diag),
            diagnostic_code=str(diag.get("code") or "UNKNOWN"),
        )
    action = _design_policy_action(diag, state, policy_profile=policy_profile)
    return DesignDiagnosticItem(
        code=str(diag.get("code") or "UNKNOWN"),
        pyfcstm_severity=str(diag.get("severity") or "warning"),
        policy_action=action,
        instance_key=state.instance_key,
        refs=copy.deepcopy(diag.get("refs") or {}),
        message=str(diag.get("message") or ""),
        suggested_fix_hints=_extract_suggested_fix_hints(diag),
        budget_remaining=state.budget_remaining,
        budget_exhausted=state.budget_exhausted,
    )


