# Custom mutation checks for NFRR DMR. Each mutant is expected to fail at least one original-passing scenario.
def run_scenarios_for_dsl(dsl: str, scenario_subset: list[TestScenario]) -> dict[str, Any]:
    c = StageContext(nl=NL_ORIGINAL, current_dsl=dsl)
    p, _ = run_sd2_parse(dsl, c)
    if not p.ok:
        return {'parse_ok': False, 'semantic_ok': False, 'sim_ok': False, 'failure_kind': 'parse_fail', 'parse': sanitize(p)}
    s, _, _ = run_sd3_semantic(dsl, c)
    if not s.ok:
        return {'parse_ok': True, 'semantic_ok': False, 'sim_ok': False, 'failure_kind': 'semantic_fail', 'semantic': sanitize(s)}
    ss, _ = freeze_scenario_set(scenario_subset, source_dsl_hash='sha256:' + sha256_text(dsl), source_inspect_hash='sha256:' + sha256_text('mutation'), scenario_set_id='mutation-probe')
    sim, _ = run_sd6_sim(dsl, ss, c)
    failing = [r.name for r in sim.scenario_results if r.status "'!= '"'pass']
    return {'parse_ok': True, 'semantic_ok': True, 'sim_ok': sim.ok, 'failure_kind': 'sim_fail' if not sim.ok else None, 'failing_scenarios': failing, 'sim': sanitize(sim)}

